import {TRAINERS,encounterPool} from '../lib/campaign.mjs';

const root=fileURLToPath(new URL('../',import.meta.url)),sql=new DatabaseSync(':memory:');
for(const name of (await fs.readdir(new URL('../drizzle/',import.meta.url))).filter(n=>/^\d.*\.sql$/.test(n)).sort())sql.exec(await fs.readFile(new URL('../drizzle/'+name,import.meta.url),'utf8'));
function prepare(query,args=[]){return {bind(...values){return prepare(query,values);},async first(){return sql.prepare(query).get(...args)||null;},async all(){return {results:sql.prepare(query).all(...args)};},async run(){const r=sql.prepare(query).run(...args);return {meta:{changes:Number(r.changes)}};}};}
globalThis.__adventureEnv={DB:{prepare,async batch(statements){sql.exec('BEGIN');try{const result=[];for(const s of statements)result.push(await s.run());sql.exec('COMMIT');return result;}catch(e){sql.exec('ROLLBACK');throw e;}}}};
globalThis.__adventureUser={userId:'adventure-qa',displayName:'탐험테스트'};globalThis.__adventureRandom=()=>.999;
async function loadTS(relative){
 let source=await fs.readFile(new URL('../'+relative,import.meta.url),'utf8');
 source=source.replace(/import\s*\{\s*env\s*\}\s*from\s*['"]cloudflare:workers['"];?/g,'const env=globalThis.__adventureEnv;');
 source=source.replace(/import\s*\{getChatGPTUser\}\s*from\s*['"]@\/app\/chatgpt-auth['"];?/g,'const getChatGPTUser=async()=>globalThis.__adventureUser;');
 source=source.replace("const random=()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296;","const random=()=>globalThis.__adventureRandom();");
 const inventoryURL=relative==='lib/local-adventure-route.ts'?await loadTS('lib/inventory.ts'):null;
 source=source.replace(/from\s*(['"])(@\/[^'"]+|\.\.?\/[^'"]+)\1/g,(_,quote,specifier)=>{
  if(specifier==='@/lib/inventory')return `from '${inventoryURL}'`;
  const url=specifier.startsWith('@/')?pathToFileURL(root+specifier.slice(2)):new URL(specifier,new URL('../'+relative,import.meta.url));return `from '${url.href}'`;
 });
 const emitted=ts.transpileModule(source,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ESNext}}).outputText;
 return 'data:text/javascript;base64,'+Buffer.from(emitted).toString('base64');
}
const route=await import(await loadTS('lib/local-adventure-route.ts'));
let state;
async function get(){const r=await route.GET(new Request('http://adventure.test/api/world'));assert.equal(r.status,200);return state=await r.json();}
async function call(action,extra={},expected=200){const r=await route.POST(new Request('http://adventure.test/api/world',{method:'POST',headers:{'content-type':'application/json',origin:'http://adventure.test'},body:JSON.stringify({action,revision:state?.revision,...extra})}));const d=await r.json();assert.equal(r.status,expected,`${action}: ${JSON.stringify(d)}`);if(expected===200)state=d;return d;}
function rawWorld(){return JSON.parse(sql.prepare('SELECT state FROM worlds WHERE user_id=?').get('adventure-qa').state);}
function seedWorld(patch){const w={...rawWorld(),...patch};sql.prepare('UPDATE worlds SET state=?,revision=revision+1 WHERE user_id=?').run(JSON.stringify(w),'adventure-qa');}
function rawMon(id){return JSON.parse(sql.prepare('SELECT data FROM pokemon_box WHERE id=?').get(id).data);}
function seedMon(id,p){sql.prepare('UPDATE pokemon_box SET species_id=?,data=? WHERE id=?').run(p.id,JSON.stringify(p),id);}
async function walkTo(tileOrTarget){const target=typeof tileOrTarget==='string'?findTile(state.world.map,tileOrTarget):tileOrTarget;assert.ok(target);const map=state.world.map,path=fieldPath(map,state.world,target),person=personTile(map[target.y]?.[target.x],map)||visibleWildTile(map[target.y]?.[target.x]),face=person&&path.length?path.pop():null;while(path.length){await call('move',{path:path.splice(0,8)});assert.equal(state.battle,null);}if(face)await call('face',{direction:face});if(person){const spot=interactionAt(state.world);assert.deepEqual([spot?.x,spot?.y],[target.x,target.y]);}else if(!['E','W','D'].includes(typeof tileOrTarget==='string'?tileOrTarget:''))assert.deepEqual([state.world.x,state.world.y],[target.x,target.y]);}
function testHealingItem(w,missing){return missing>120&&w.max_potions>0?'max':missing>120&&w.full_restores>0?'fullrestore':missing>60&&w.hyper_potions>0?'hyper':missing>60&&w.max_potions>0?'max':missing>60&&w.full_restores>0?'fullrestore':w.super_potions>0?'super':w.potions>0?'potion':w.hyper_potions>0?'hyper':w.max_potions>0?'max':w.full_restores>0?'fullrestore':null;}
test('healing strategy uses only available recovery supplies',()=>{assert.equal(testHealingItem({max_potions:0,full_restores:1,super_potions:1},100),'fullrestore');assert.equal(testHealingItem({max_potions:0,full_restores:0,super_potions:1},100),'super');assert.equal(testHealingItem({},100),null);});
async function battle({allowHealing=false,allowRevive=false,trace=null,stats=null}={}){let turns=0,healedLast=false,revived=false;while(state.battle){assert.ok(turns++<180,'battle finishes');const b=state.battle;if(b.ended){const coins=state.wallet.coins;await call('move',{direction:'up'},409);await get();assert.equal(state.battle.ended,true);await call('battleContinue');assert.equal(state.wallet.coins,coins);await call('battleContinue',{},409);continue;}const q=b.requests[0],p=b.teams[0][b.active[0]],foe=b.teams[1][b.active[1]];if(allowRevive&&!revived&&q.kind==='move'&&p.hp>p.maxHp*.6&&state.inventory.revive>0){const target=b.teams[0].find(member=>member.hp<=0);if(target){await call('battleRevive',{boxId:target.boxId});if(stats)stats.revives=(stats.revives||0)+1;revived=true;healedLast=false;continue;}}if(allowHealing&&!healedLast&&q.kind==='move'&&p.hp>0&&p.hp<=p.maxHp*.6&&(state.wallet.max_potions>0||state.wallet.full_restores>0||state.wallet.hyper_potions>0||state.wallet.super_potions>0||state.wallet.potions>0)){const item=testHealingItem(state.wallet,p.maxHp-p.hp);await call('use',{item});healedLast=true;if(trace)trace.push(...(state.battle?.log||[]));continue;}healedLast=false;const command=q.kind==='switch'?{type:'switch',slot:q.switches.sort((a,b)=>b.hp-a.hp)[0].slot}:{type:'move',move:q.moves.filter(m=>!m.disabled&&m.pp>0).map(m=>({m,score:(moves[m.name]?.power||0)*effectiveness(moves[m.name]?.type,foe.types)*(p.types.includes(moves[m.name]?.type)?1.5:1)})).sort((a,b)=>b.score-a.score)[0].m.name};await call('battle',{command});if(trace)trace.push(...(state.battle?.log||[]));}return turns;}

